-- Preserve system/service updates in the audit trail even when auth.uid() is null.
create or replace function public.audit_spike_abuse_case_change() returns trigger language plpgsql security definer set search_path=pg_catalog,public as $function$ declare v_actor uuid:=auth.uid(); v_role text:='system'; begin if v_actor is not null then select p.role into v_role from public.profiles p where p.id=v_actor; v_role:=coalesce(v_role,'authenticated'); end if; insert into public.admin_audit(actor_id,action,target_user_id,role,details) values(v_actor,'abuse_case_updated',new.subject_user_id,v_role,jsonb_build_object('case_id',new.id,'source',new.source,'source_id',new.source_id,'reporter_id',new.reporter_id,'before',jsonb_build_object('status',old.status,'severity',old.severity,'assigned_to',old.assigned_to,'resolution',old.resolution),'after',jsonb_build_object('status',new.status,'severity',new.severity,'assigned_to',new.assigned_to,'resolution',new.resolution))); return new; end; $function$;
revoke all on function public.audit_spike_abuse_case_change() from public,anon,authenticated;
